// xxqmc ONLINE — TEK DOSYA (oyun + sunucu bir arada)
// Render ayarı: Build Command = npm install express socket.io   |   Start Command = node server.js
// Başka dosya gerekmez.
const GAME_B64 = '';

// Çalıştırma:  npm i express socket.io   ->   node server.js
// Oyun dosyasını (xxqmc.html) bu dosyayla aynı klasöre koy.
const path = require('path');
const http = require('http');
const express = require('express');
const { Server } = require('socket.io');

const app = express();
const srv = http.createServer(app);
const io = new Server(srv, { cors: { origin: '*' } });

const GAME_HTML = Buffer.from(GAME_B64, 'base64');
app.get('/', (_, res) => res.type('html').send(GAME_HTML));

const rooms = new Map();

function makeRoom(code) {
  return {
    code,
    seed: (Math.random() * 4294967296) >>> 0, // herkes için aynı End haritası
    players: new Map(),                        // id -> son oyuncu durumu
    main: new Map(),                           // "x,y,z" -> {x,y,z,b} (ana dünya değişiklikleri)
    end: new Map(),                            // "x,y,z" -> blok (End değişiklikleri)
    endPlayers: new Set(),                     // şu an End'de olan socket id'leri
    host: null,                                // ejderhayı simüle eden oyuncu
    sync: null,                                // ejderhanın son durumu
    cr: null,                                  // End kristalleri [[x,y,z,heal],...]
    dead: false,                               // ejderha öldü mü
    emptyTimer: null
  };
}

function leaveEnd(room, id) {
  if (!room.endPlayers.delete(id)) return;
  if (room.host === id) {
    room.host = null;
    const next = room.endPlayers.values().next().value;
    if (next) {
      room.host = next;
      io.to(next).emit('endHost', { sync: room.sync });
    }
  }
}

function leaveRoom(socket) {
  const code = socket.data.room;
  if (!code) return;
  const room = rooms.get(code);
  socket.leave(code);
  socket.data.room = null;
  if (!room) return;
  leaveEnd(room, socket.id);
  room.players.delete(socket.id);
  socket.to(code).emit('playerLeft', socket.id);
  if (room.players.size === 0) {
    // oda boşalırsa 10 dk sonra silinir (kodla geri dönülebilsin)
    room.emptyTimer = setTimeout(() => {
      if (room.players.size === 0) rooms.delete(code);
    }, 10 * 60 * 1000);
  }
}

io.on('connection', (socket) => {
  socket.data.name = String((socket.handshake.auth && socket.handshake.auth.username) || 'Oyuncu').slice(0, 16);
  socket.data.room = null;
  const R = () => rooms.get(socket.data.room);

  socket.on('joinRoom', (data, ack) => {
    ack = typeof ack === 'function' ? ack : () => {};
    const code = String((data && data.code) || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8);
    if (code.length < 3) return ack({ ok: false, error: 'Oda kodu geçersiz' });
    let room = rooms.get(code);
    if (!room) {
      if (!(data && data.create)) return ack({ ok: false, error: 'Böyle bir oda yok' });
      room = makeRoom(code);
      rooms.set(code, room);
    }
    if (room.players.size >= 16) return ack({ ok: false, error: 'Oda dolu (en fazla 16 kişi)' });
    if (socket.data.room) leaveRoom(socket);
    clearTimeout(room.emptyTimer);

    socket.join(code);
    socket.data.room = code;
    const me = { id: socket.id, name: socket.data.name, x: 48, y: 24, z: 48, yaw: 0, pitch: 0 };
    room.players.set(socket.id, me);

    // sıra önemli: önce oda bilgisi (seed), sonra oyuncular ve dünya değişiklikleri
    socket.emit('roomInfo', { seed: room.seed, dead: room.dead });
    socket.emit('players', [...room.players.values()]);
    socket.emit('worldChanges', [...room.main.values()]);
    socket.to(code).emit('playerJoined', me);
    ack({ ok: true, count: room.players.size });
  });

  socket.on('playerMove', (p) => {
    const room = R(); if (!room || !p) return;
    const pl = { ...p, id: socket.id, name: socket.data.name };
    room.players.set(socket.id, pl);
    socket.to(room.code).emit('playerMoved', pl);
  });

  socket.on('blockChange', (c) => {
    const room = R(); if (!room || !c) return;
    const key = c.x + ',' + c.y + ',' + c.z;
    if (c.e) room.end.set(key, c.b);
    else room.main.set(key, { x: c.x, y: c.y, z: c.z, b: c.b });
    socket.to(room.code).emit('blockChange', c);
  });

  // ---- ORTAK EJDERHA ----
  socket.on('endEnter', (_d, ack) => {
    const room = R(); if (!room) return;
    room.endPlayers.add(socket.id);
    if (!room.host || !room.endPlayers.has(room.host)) room.host = socket.id; // End'e ilk giren ev sahibi
    if (typeof ack === 'function') {
      ack({
        host: room.host === socket.id,
        dead: room.dead,
        changes: [...room.end.entries()],
        cr: room.cr,
        sync: room.sync
      });
    }
  });

  socket.on('endLeave', () => { const room = R(); if (room) leaveEnd(room, socket.id); });

  socket.on('dragonState', (m) => {
    const room = R(); if (!room || room.host !== socket.id || !m) return; // sadece ev sahibi
    room.sync = m;
    if (m.cr) room.cr = m.cr;
    socket.to(room.code).emit('dragonState', m);
  });

  socket.on('dragonHit', (d) => {
    const room = R(); if (!room || !room.host || room.host === socket.id) return;
    io.to(room.host).emit('dragonHit', d); // hasarı ev sahibine ilet
  });

  socket.on('dragonDead', (d) => {
    const room = R(); if (!room || room.dead) return;
    room.dead = true; room.sync = null; room.cr = null;
    socket.to(room.code).emit('dragonDead', d);
  });

  socket.on('crystalBoom', (c) => {
    const room = R(); if (!room || !c) return;
    if (room.cr) room.cr = room.cr.filter(k => Math.hypot(k[0] - c.x, k[1] - c.y, k[2] - c.z) >= 0.5);
    socket.to(room.code).emit('crystalBoom', c);
  });

  socket.on('crystalAdd', (c) => {
    const room = R(); if (!room || !c) return;
    if (room.cr) room.cr.push([c.x, c.y, c.z, 0]);
    socket.to(room.code).emit('crystalAdd', c);
  });

  socket.on('shieldBreak', (d) => { if (d && d.to) io.to(d.to).emit('shieldBreak'); });

  socket.on('disconnect', () => leaveRoom(socket));
});

const PORT = process.env.PORT || 3000;
srv.listen(PORT, () => console.log('xxqmc sunucusu çalışıyor: http://localhost:' + PORT));
